import { describe, expect, it } from "@jest/globals";
import { shippingCost, TIERS } from "../shipping";

describe("shippingCost", () => {
  it("charges each weight band at its own rate", () => {
    const weightKg = 23.5;
    let expected = 0;
    let remaining = weightKg;
    for (const tier of TIERS) {
      const inBand = Math.min(remaining, tier.upToKg - tier.fromKg);
      if (inBand <= 0) break;
      expected += inBand * tier.ratePerKg;
      remaining -= inBand;
    }
    expect(shippingCost(weightKg)).toBeCloseTo(expected, 2);
  });
});

