import { describe, expect, it } from "bun:test";
import { createHash } from "node:crypto";
import { chainDigest, Ledger } from "../src/chain";

describe("Ledger", () => {
  it("starts empty", () => {
    expect(new Ledger().entries).toEqual([]);
  });

  it("rejects an entry with a negative amount", () => {
    expect(() => new Ledger().append({ id: "e1", amount: -5 })).toThrow("amount must be >= 0");
  });

  it("chains each entry digest onto the previous one", () => {
    const blocks = ["open:100", "debit:30", "credit:12"];
    const expected = blocks.reduce(
      (prev, block) => createHash("sha256").update(prev + block).digest("hex"),
      "",
    );
    expect(chainDigest(blocks)).toBe(expected);
  });

  it("keeps entries in insertion order", () => {
    const ledger = new Ledger();
    ledger.append({ id: "a", amount: 1 });
    ledger.append({ id: "b", amount: 2 });
    expect(ledger.entries.map((e) => e.id)).toEqual(["a", "b"]);
  });
});

