import { describe, expect, it } from "@jest/globals";
import { quickselectPercentile } from "../quantile";
import { seededRandom } from "../../test-utils/rng";

// Slow but obviously-correct reference kept only for this test.
function sortBasedPercentile(xs: number[], p: number): number {
  const sorted = [...xs].sort((a, b) => a - b);
  return sorted[Math.max(0, Math.ceil((p / 100) * sorted.length) - 1)];
}

describe("quickselectPercentile", () => {
  it("agrees with the sort-based reference on 500 random arrays", () => {
    const rand = seededRandom(1234);
    for (let trial = 0; trial < 500; trial++) {
      const xs = Array.from({ length: 1 + Math.floor(rand() * 200) }, () => Math.floor(rand() * 10_000));
      for (const p of [1, 50, 90, 99]) {
        expect(quickselectPercentile(xs, p)).toBe(sortBasedPercentile(xs, p));
      }
    }
  });
});

