test("streaming hasher matches the one-shot crc32 regardless of chunking", () => {
  const data = Buffer.from("x".repeat(70_000) + "tail-bytes");
  for (const chunkSize of [1, 7, 4096, 65_536]) {
    const h = new Crc32Stream();
    for (let off = 0; off < data.length; off += chunkSize) {
      h.update(data.subarray(off, off + chunkSize));
    }
    expect(h.digest()).toBe(crc32(data));
  }
});

