import { describe, expect, it } from "bun:test";
import Decimal from "decimal.js";
import { amortizationSchedule } from "../src/schedule";

describe("amortizationSchedule (float fast path)", () => {
  it("stays within a cent of an arbitrary-precision Decimal oracle", () => {
    const principal = new Decimal(312_500);
    const r = new Decimal(0.0575).div(12);
    const n = 360;
    const payment = principal.mul(r).div(new Decimal(1).minus(r.plus(1).pow(-n)));
    let balance = principal;
    const rows = amortizationSchedule(312_500, 0.0575, n);
    rows.forEach((row) => {
      const interest = balance.mul(r);
      balance = balance.minus(payment.minus(interest));
      expect(Math.abs(row.balance - balance.toNumber())).toBeLessThan(0.01);
    });
  });
});

