import { RateLimiter } from "../rateLimit";

describe("RateLimiter", () => {
  it("allows five attempts then blocks", () => {
    const clock = { now: jest.fn(() => 1_000) };
    const rl = new RateLimiter({ max: 5, windowMs: 60_000, clock });
    for (let i = 0; i < 5; i++) expect(rl.attempt("ip-1")).toBe(true);
    expect(rl.attempt("ip-1")).toBe(false);
  });

  it("resets after the window passes", () => {
    let t = 0;
    const rl = new RateLimiter({ max: 1, windowMs: 1_000, clock: { now: () => t } });
    expect(rl.attempt("ip-2")).toBe(true);
    t = 1_001;
    expect(rl.attempt("ip-2")).toBe(true);
  });
});

